## Object.create()

`Object.create(proto)` crea un nuevo objeto vacío cuyo `[[Prototype]]` apunta directamente a `proto`. Es la forma más explícita y limpia de establecer herencia prototípica.

```javascript
const proto = { saludar() { return `Hola, soy ${this.nombre}`; } };

const obj = Object.create(proto);
obj.nombre = 'Ana';

console.log(obj.saludar()); // 'Hola, soy Ana'
console.log(Object.getPrototypeOf(obj) === proto); // true
```

---

## Object.create(null) — objeto sin prototipo

Pasando `null` se crea un objeto completamente limpio, sin herencia de `Object.prototype`:

```javascript
const mapa = Object.create(null);
mapa.clave = 'valor';

// No tiene toString, hasOwnProperty, etc.
console.log(mapa.toString); // undefined
console.log(Object.getPrototypeOf(mapa)); // null

// Ideal para diccionarios seguros (sin colisión con métodos heredados)
const config = Object.create(null);
config.constructor = 'mi valor'; // Sin problema — no pisa nada
```

---

## Segundo argumento: descriptores de propiedad

`Object.create(proto, descriptores)` permite definir propiedades con control total:

```javascript
const persona = Object.create(
  { saludar() { return `Hola, ${this.nombre}`; } }, // proto
  {
    nombre: {
      value: 'Carlos',
      writable: true,     // ¿Se puede modificar?
      enumerable: true,   // ¿Aparece en for...in?
      configurable: true, // ¿Se puede redefinir/eliminar?
    },
    edad: {
      value: 30,
      writable: false,    // Solo lectura
      enumerable: true,
      configurable: false,
    },
  }
);

console.log(persona.saludar()); // 'Hola, Carlos'
persona.edad = 99;  // Silencioso en modo normal, error en strict mode
console.log(persona.edad); // 30 — no cambió (writable: false)
```

---

## Comparación con otras formas de crear objetos

```javascript
// 1. Literal — prototipo es Object.prototype
const a = { x: 1 };

// 2. new Object() — igual que literal
const b = new Object();
b.x = 1;

// 3. Object.create(proto) — prototipo explícito
const proto = { metodo() {} };
const c = Object.create(proto);
c.x = 1;

// 4. Object.create(null) — sin prototipo
const d = Object.create(null);
d.x = 1;

console.log(Object.getPrototypeOf(a) === Object.prototype); // true
console.log(Object.getPrototypeOf(c) === proto);            // true
console.log(Object.getPrototypeOf(d));                      // null
```

---

## Patrón: función fábrica con Object.create

```javascript
const vehiculoProto = {
  arrancar() {
    return `${this.marca} arrancando...`;
  },
  info() {
    return `${this.marca} ${this.modelo} (${this.anio})`;
  },
};

function crearVehiculo(marca, modelo, anio) {
  const v = Object.create(vehiculoProto);
  v.marca = marca;
  v.modelo = modelo;
  v.anio = anio;
  return v;
}

const moto = crearVehiculo('Honda', 'CB500', 2023);
const coche = crearVehiculo('Toyota', 'Corolla', 2022);

console.log(moto.arrancar()); // 'Honda arrancando...'
console.log(coche.info());    // 'Toyota Corolla (2022)'

// Los métodos son compartidos — solo existe UNA copia
console.log(moto.arrancar === coche.arrancar); // true
```

Este es el patrón más eficiente: los métodos viven en el prototipo (una sola copia), los datos en cada objeto.

examples.code:
// Herencia de múltiples niveles con Object.create
const entidad = {
  tipo: 'entidad',
  toString() { return `[${this.tipo}: ${this.nombre}]`; },
};

const usuario = Object.create(entidad);
usuario.tipo = 'usuario';
usuario.iniciarSesion = function () {
  return `${this.nombre} ha iniciado sesión`;
};

const admin = Object.create(usuario);
admin.tipo = 'admin';
admin.borrarTodo = function () {
  return `${this.nombre} borró todo`;
};

const superAdmin = Object.create(admin);
superAdmin.nombre = 'root';

console.log(superAdmin.toString());       // '[admin: root]'
console.log(superAdmin.iniciarSesion());  // 'root ha iniciado sesión'
console.log(superAdmin.borrarTodo());     // 'root borró todo'

// Clonar con prototipo preservado
function clonarObjeto(obj) {
  const proto = Object.getPrototypeOf(obj);
  const clon = Object.create(proto);
  return Object.assign(clon, obj);
}

const proto = { metodo() { return this.valor * 2; } };
const original = Object.create(proto);
original.valor = 21;

const clon = clonarObjeto(original);
clon.valor = 5;

console.log(original.metodo()); // 42
console.log(clon.metodo());     // 10
console.log(Object.getPrototypeOf(clon) === proto); // true

